-- 0001_foundation.sql — Phase 0
--
-- Identity, org structure, authorization grants, sessions, settings, the
-- append-only hash-chained audit log, and the job queue.
--
-- Run as the schema owner role (pdms_owner) via `pdms migrate`. The running
-- application connects as pdms_app, which owns nothing and receives only the
-- explicit per-table grants at the bottom of this file (deny by default).
-- Both roles are created by deploy/postgres/00_roles.sql before migrating.
-- Requires PostgreSQL 15+ (UNIQUE NULLS NOT DISTINCT).
--
-- Primary keys are UUIDv7 generated by the application (time-ordered).

-- ---------------------------------------------------------------------------
-- Enumerations
-- ---------------------------------------------------------------------------

CREATE TYPE user_status       AS ENUM ('active', 'disabled', 'departed');
CREATE TYPE membership_source AS ENUM ('manual', 'idp');
CREATE TYPE auth_method       AS ENUM ('oidc', 'local', 'api_token', 'ics_token', 'system');
CREATE TYPE permission        AS ENUM ('view', 'create', 'edit', 'delete', 'approve',
                                       'manage_permissions', 'export');
CREATE TYPE acl_scope         AS ENUM ('global', 'department', 'document');
CREATE TYPE audit_category    AS ENUM ('content', 'metadata', 'permission', 'admin',
                                       'auth', 'access', 'workflow', 'notification', 'system');
CREATE TYPE audit_outcome     AS ENUM ('success', 'denied', 'failure');
CREATE TYPE job_status        AS ENUM ('pending', 'running', 'succeeded', 'failed', 'dead');

-- ---------------------------------------------------------------------------
-- Organization structure
-- ---------------------------------------------------------------------------

CREATE TABLE departments (
    id          uuid PRIMARY KEY,
    code        text NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9_-]{1,32}$'),
    name        text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    external_id text UNIQUE,                       -- e.g. Entra group object id
    is_active   boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id             uuid PRIMARY KEY,
    display_name   text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 200),
    email          text NOT NULL CHECK (email ~ '^[^@\s]+@[^@\s]+$'),
    -- Entra: issuer is the tenant issuer URL, subject is the `oid` claim
    -- (stable across apps), not the pairwise `sub`.
    oidc_issuer    text,
    oidc_subject   text,
    status         user_status NOT NULL DEFAULT 'active',
    last_login_at  timestamptz,
    deactivated_at timestamptz,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_oidc_pair CHECK ((oidc_issuer IS NULL) = (oidc_subject IS NULL)),
    CONSTRAINT users_oidc_identity_key UNIQUE (oidc_issuer, oidc_subject)
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

-- Break-glass local accounts only. Presence of a row enables local login.
CREATE TABLE local_credentials (
    user_id             uuid PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    password_hash       text NOT NULL CHECK (password_hash LIKE '$argon2id$%'),
    totp_secret_enc     bytea,                     -- AES-256-GCM, key derived from PDMS_SECRET_KEY
    totp_last_step      bigint,                    -- last accepted TOTP time step (replay protection)
    failed_attempts     integer NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0),
    locked_until        timestamptz,
    password_changed_at timestamptz NOT NULL DEFAULT now(),
    created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE department_members (
    department_id uuid NOT NULL REFERENCES departments (id),
    user_id       uuid NOT NULL REFERENCES users (id),
    is_primary    boolean NOT NULL DEFAULT false,
    source        membership_source NOT NULL DEFAULT 'manual',
    added_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (department_id, user_id)
);
CREATE INDEX department_members_user_idx ON department_members (user_id);
CREATE UNIQUE INDEX department_members_one_primary ON department_members (user_id) WHERE is_primary;

CREATE TABLE groups (
    id          uuid PRIMARY KEY,
    name        text NOT NULL UNIQUE CHECK (length(name) BETWEEN 1 AND 200),
    description text NOT NULL DEFAULT '',
    external_id text UNIQUE,                       -- Entra group object id when synced
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE group_members (
    group_id uuid NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
    user_id  uuid NOT NULL REFERENCES users (id),
    source   membership_source NOT NULL DEFAULT 'manual',
    added_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (group_id, user_id)
);
CREATE INDEX group_members_user_idx ON group_members (user_id);

-- Roles carry system capabilities (hard-coded per system role key in the authz
-- crate) and can be ACL subjects. Display names are editable so an
-- organization can call `legal_counsel` "General Counsel's Office".
CREATE TABLE roles (
    id          uuid PRIMARY KEY,
    key         text NOT NULL UNIQUE CHECK (key ~ '^[a-z][a-z0-9_]{1,63}$'),
    name        text NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    description text NOT NULL DEFAULT '',
    is_system   boolean NOT NULL DEFAULT false,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- department_id NULL = organization-wide; otherwise the role applies only to
-- documents/appointments of that department (e.g. Department Head of Operations).
CREATE TABLE role_assignments (
    id            uuid PRIMARY KEY,
    role_id       uuid NOT NULL REFERENCES roles (id),
    user_id       uuid NOT NULL REFERENCES users (id),
    department_id uuid REFERENCES departments (id),
    source        membership_source NOT NULL DEFAULT 'manual',
    granted_by    uuid REFERENCES users (id),
    granted_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT role_assignments_key UNIQUE NULLS NOT DISTINCT (role_id, user_id, department_id)
);
CREATE INDEX role_assignments_user_idx ON role_assignments (user_id);

-- Maps an IdP group (claim or Graph) to exactly one local target. Memberships
-- with source = 'idp' are reconciled at each login; 'manual' ones are untouched.
CREATE TABLE idp_group_mappings (
    id                 uuid PRIMARY KEY,
    idp_group_id       text NOT NULL,
    description        text NOT NULL DEFAULT '',
    department_id      uuid REFERENCES departments (id),
    group_id           uuid REFERENCES groups (id) ON DELETE CASCADE,
    role_id            uuid REFERENCES roles (id),
    role_department_id uuid REFERENCES departments (id),
    created_at         timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT idp_group_mappings_one_target
        CHECK (num_nonnulls(department_id, group_id, role_id) = 1),
    CONSTRAINT idp_group_mappings_role_dept
        CHECK (role_department_id IS NULL OR role_id IS NOT NULL),
    CONSTRAINT idp_group_mappings_key
        UNIQUE NULLS NOT DISTINCT (idp_group_id, department_id, group_id, role_id, role_department_id)
);

-- ---------------------------------------------------------------------------
-- Sessions and settings
-- ---------------------------------------------------------------------------

-- The cookie holds a 256-bit random token; only its SHA-256 is stored. CSRF
-- tokens are an HMAC of the session token, so nothing extra is stored for them.
CREATE TABLE sessions (
    id           uuid PRIMARY KEY,
    token_hash   bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    user_id      uuid NOT NULL REFERENCES users (id),
    auth_method  auth_method NOT NULL CHECK (auth_method IN ('oidc', 'local')),
    ip           inet,
    user_agent   text,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),   -- idle timeout from config
    expires_at   timestamptz NOT NULL,                 -- absolute timeout
    revoked_at   timestamptz
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

-- Runtime-editable settings (notification defaults, audit forwarding, etc.).
-- Bootstrap config (DB URL, secrets, org name) lives in config files/env.
CREATE TABLE app_settings (
    key        text PRIMARY KEY CHECK (key ~ '^[a-z][a-z0-9_.]{1,127}$'),
    value      jsonb NOT NULL,
    updated_by uuid REFERENCES users (id),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Authorization grants (allow-only; deny by default)
-- ---------------------------------------------------------------------------
--
-- Exactly one subject column and a scope-consistent target. Revocation deletes
-- the row (the audit entry keeps the before-image). Rules evaluated in the
-- authz crate:
--   * global/department grants apply only to documents with inherit_acl = true
--     and is_confidential = false; document grants always apply.
--   * a role subject matches if the user holds the role org-wide or for the
--     document's department.
--   * any non-`create` permission implies `view`.
CREATE TABLE acl_entries (
    id                    uuid PRIMARY KEY,
    subject_user_id       uuid REFERENCES users (id),
    subject_group_id      uuid REFERENCES groups (id) ON DELETE CASCADE,
    subject_department_id uuid REFERENCES departments (id),
    subject_role_id       uuid REFERENCES roles (id),
    scope                 acl_scope NOT NULL,
    scope_department_id   uuid REFERENCES departments (id),
    scope_document_id     uuid,          -- FK to documents (id) added in 0002
    permission            permission NOT NULL,
    granted_by            uuid REFERENCES users (id),
    granted_at            timestamptz NOT NULL DEFAULT now(),
    expires_at            timestamptz,
    reason                text NOT NULL DEFAULT '',
    CONSTRAINT acl_entries_one_subject CHECK (
        num_nonnulls(subject_user_id, subject_group_id, subject_department_id, subject_role_id) = 1),
    CONSTRAINT acl_entries_scope_target CHECK (
           (scope = 'global'     AND scope_department_id IS NULL     AND scope_document_id IS NULL)
        OR (scope = 'department' AND scope_department_id IS NOT NULL AND scope_document_id IS NULL)
        OR (scope = 'document'   AND scope_department_id IS NULL     AND scope_document_id IS NOT NULL)),
    CONSTRAINT acl_entries_no_document_create CHECK (NOT (scope = 'document' AND permission = 'create')),
    CONSTRAINT acl_entries_key UNIQUE NULLS NOT DISTINCT (
        subject_user_id, subject_group_id, subject_department_id, subject_role_id,
        scope, scope_department_id, scope_document_id, permission)
);
CREATE INDEX acl_entries_document_idx   ON acl_entries (scope_document_id)   WHERE scope_document_id IS NOT NULL;
CREATE INDEX acl_entries_department_idx ON acl_entries (scope_department_id) WHERE scope_department_id IS NOT NULL;
CREATE INDEX acl_entries_subject_user_idx  ON acl_entries (subject_user_id)       WHERE subject_user_id IS NOT NULL;
CREATE INDEX acl_entries_subject_group_idx ON acl_entries (subject_group_id)      WHERE subject_group_id IS NOT NULL;
CREATE INDEX acl_entries_subject_dept_idx  ON acl_entries (subject_department_id) WHERE subject_department_id IS NOT NULL;
CREATE INDEX acl_entries_subject_role_idx  ON acl_entries (subject_role_id)       WHERE subject_role_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Audit log: append-only, hash-chained
-- ---------------------------------------------------------------------------
--
-- Write protocol (one transaction, as the LAST step of the business change):
--   1. SELECT * FROM audit_lock_head();      -- row lock, held until commit
--   2. for each entry: seq = head.seq + 1, prev_hash = head.entry_hash,
--      entry_hash = SHA-256(canonical(entry)) computed in Rust (hash_version 1)
--   3. INSERT; the BEFORE INSERT trigger re-checks linkage and advances the head.
-- Every hashed column is supplied by the application (no defaults), so the
-- verifier can recompute hashes from stored rows alone.

CREATE TABLE audit_chain_head (
    singleton  boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    seq        bigint NOT NULL CHECK (seq >= 0),
    entry_hash bytea NOT NULL CHECK (octet_length(entry_hash) = 32)
);
INSERT INTO audit_chain_head (singleton, seq, entry_hash)
VALUES (true, 0, decode(repeat('00', 32), 'hex'));   -- genesis

CREATE TABLE audit_log (
    seq               bigint PRIMARY KEY CHECK (seq > 0),
    id                uuid NOT NULL UNIQUE,
    occurred_at       timestamptz NOT NULL,          -- UTC, microsecond precision
    category          audit_category NOT NULL,
    action            text NOT NULL CHECK (action ~ '^[a-z_]+(\.[a-z_]+)+$'),  -- e.g. document.metadata_updated
    outcome           audit_outcome NOT NULL,
    actor_user_id     uuid,                          -- no FK: audit must outlive anything it references
    actor_display     text,
    actor_auth_method auth_method NOT NULL,
    actor_ip          inet,
    actor_user_agent  text,
    api_token_id      uuid,
    request_id        text,
    object_type       text NOT NULL,
    object_id         text,
    object_label      text,
    document_id       uuid,                          -- denormalized for per-document timelines
    department_id     uuid,                          -- denormalized for filtering
    changes           jsonb,                         -- [{field, before, after}]; no floats
    context           jsonb NOT NULL,                -- e.g. {"request_ref": "REQ-2026-014"}
    hash_version      smallint NOT NULL,
    prev_hash         bytea NOT NULL CHECK (octet_length(prev_hash) = 32),
    entry_hash        bytea NOT NULL UNIQUE CHECK (octet_length(entry_hash) = 32)
);
CREATE INDEX audit_log_occurred_idx   ON audit_log (occurred_at);
CREATE INDEX audit_log_actor_idx      ON audit_log (actor_user_id, occurred_at);
CREATE INDEX audit_log_document_idx   ON audit_log (document_id, seq)   WHERE document_id IS NOT NULL;
CREATE INDEX audit_log_department_idx ON audit_log (department_id, occurred_at) WHERE department_id IS NOT NULL;
CREATE INDEX audit_log_object_idx     ON audit_log (object_type, object_id);
CREATE INDEX audit_log_action_idx     ON audit_log (action, occurred_at);
CREATE INDEX audit_log_category_idx   ON audit_log (category, occurred_at);

CREATE FUNCTION audit_reject_modification() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% is append-only: % rejected', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER audit_log_no_update_delete
    BEFORE UPDATE OR DELETE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_reject_modification();
CREATE TRIGGER audit_log_no_truncate
    BEFORE TRUNCATE ON audit_log
    FOR EACH STATEMENT EXECUTE FUNCTION audit_reject_modification();
CREATE TRIGGER audit_chain_head_no_delete
    BEFORE DELETE ON audit_chain_head
    FOR EACH ROW EXECUTE FUNCTION audit_reject_modification();
CREATE TRIGGER audit_chain_head_no_truncate
    BEFORE TRUNCATE ON audit_chain_head
    FOR EACH STATEMENT EXECUTE FUNCTION audit_reject_modification();

-- Locks and returns the chain head. SECURITY DEFINER because FOR UPDATE needs
-- UPDATE privilege, which pdms_app must not have on audit_chain_head.
CREATE FUNCTION audit_lock_head(OUT seq bigint, OUT entry_hash bytea)
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
    SELECT h.seq, h.entry_hash FROM public.audit_chain_head h WHERE h.singleton FOR UPDATE
$$;

CREATE FUNCTION audit_link_chain() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
    head_seq  bigint;
    head_hash bytea;
BEGIN
    SELECT h.seq, h.entry_hash INTO head_seq, head_hash
      FROM public.audit_chain_head h WHERE h.singleton FOR UPDATE;
    IF NEW.seq <> head_seq + 1 OR NEW.prev_hash <> head_hash THEN
        RAISE EXCEPTION 'audit chain mismatch: expected seq % with prev_hash %',
            head_seq + 1, encode(head_hash, 'hex')
            USING ERRCODE = 'serialization_failure';
    END IF;
    UPDATE public.audit_chain_head SET seq = NEW.seq, entry_hash = NEW.entry_hash WHERE singleton;
    RETURN NEW;
END
$$;

CREATE TRIGGER audit_log_link_chain
    BEFORE INSERT ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_link_chain();

-- ---------------------------------------------------------------------------
-- Job queue (claimed with SELECT ... FOR UPDATE SKIP LOCKED; lease-based recovery)
-- ---------------------------------------------------------------------------

CREATE TABLE jobs (
    id               uuid PRIMARY KEY,
    queue            text NOT NULL DEFAULT 'default',
    kind             text NOT NULL,
    payload          jsonb NOT NULL,
    status           job_status NOT NULL DEFAULT 'pending',
    priority         smallint NOT NULL DEFAULT 0,
    run_at           timestamptz NOT NULL DEFAULT now(),
    attempts         integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts     integer NOT NULL DEFAULT 8 CHECK (max_attempts > 0),
    idempotency_key  text UNIQUE,                  -- enqueue is ON CONFLICT DO NOTHING
    locked_by        text,
    lease_expires_at timestamptz,
    last_error       text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    finished_at      timestamptz,
    CONSTRAINT jobs_running_has_lease CHECK (status <> 'running' OR lease_expires_at IS NOT NULL)
);
CREATE INDEX jobs_ready_idx ON jobs (queue, priority DESC, run_at) WHERE status = 'pending';
CREATE INDEX jobs_lease_idx ON jobs (lease_expires_at) WHERE status = 'running';

-- ---------------------------------------------------------------------------
-- Seed data
-- ---------------------------------------------------------------------------

INSERT INTO roles (id, key, name, description, is_system) VALUES
    (gen_random_uuid(), 'admin',           'Administrator',
        'System administration: users, departments, settings, permission management.', true),
    (gen_random_uuid(), 'auditor',         'Auditor',
        'Read and export the audit log; run integrity verification.', true),
    (gen_random_uuid(), 'records_officer', 'Records Officer',
        'Build records request packages from documents they can view.', true),
    (gen_random_uuid(), 'legal_counsel',   'Legal Counsel',
        'Legal review/approval step (rename, e.g. "General Counsel''s Office").', true),
    (gen_random_uuid(), 'department_head', 'Department Head',
        'Department-scoped notification recipient and default approver.', true);

-- Administrators may view and manage permissions on non-confidential documents.
-- Confidential documents require an explicit document-scope grant (audited).
INSERT INTO acl_entries (id, subject_role_id, scope, permission, reason)
SELECT gen_random_uuid(), r.id, 'global', p.perm, 'seeded default for administrators'
  FROM roles r CROSS JOIN (VALUES ('view'::permission), ('manage_permissions'::permission)) AS p (perm)
 WHERE r.key = 'admin';

-- ---------------------------------------------------------------------------
-- Privileges for the application role (explicit; nothing implied)
-- ---------------------------------------------------------------------------

REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO pdms_app;

-- Users and departments are deactivated, never deleted.
GRANT SELECT, INSERT, UPDATE         ON departments, users, groups, roles, app_settings TO pdms_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON local_credentials, department_members, group_members,
                                        role_assignments, idp_group_mappings, sessions,
                                        acl_entries, jobs TO pdms_app;

GRANT SELECT, INSERT ON audit_log        TO pdms_app;
-- Lets the server refuse to start against a schema older than the binary.
GRANT SELECT         ON _sqlx_migrations TO pdms_app;
GRANT SELECT         ON audit_chain_head TO pdms_app;

REVOKE ALL ON FUNCTION audit_lock_head()           FROM PUBLIC;
REVOKE ALL ON FUNCTION audit_link_chain()          FROM PUBLIC;
REVOKE ALL ON FUNCTION audit_reject_modification() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audit_lock_head() TO pdms_app;
